mapper.select:
SELECT /* User.retrieveUserInfo */ USER_NAME , SYSTEM_CODE , LANGUAGE_CODE , TIMEZONE_TYPE_CODE , TO_CHAR( APPLICATION_USER_ID ) AS APPLICATION_USER_ID , TO_CHAR( EMPLOYEE_ID ) AS EMPLOYEE_ID , MAIL_ADDR AS MAIL_ADDR , SUBSTR(mail_addr,1,INSTR(MAIL_ADDR,'@')-1) AS SSO_ID , NVL(FULL_NAME_LOCAL,ENGLISH_FULL_NAME) as "FULL_NAME_LOCAL" , DEPARTMENT_CODE , TITLE_NAME , POSITION_CODE , POSITION_NAME , ORGANIZATION_NAME_ENG as "ORGANIZATION_NAME" , OFFICE_PHONE_NUMBER , NVL(SCREEN_DESIGN_THEME_ID, 'A' ) AS SCREEN_DESIGN_THEME_ID , NVL( TO_CHAR( DEFAULT_ORG_ID ), '89' ) AS DEFAULT_ORG_ID , DEFAULT_ORG_NAME , DEFAULT_ORG_SHORT_CODE , DEFAULT_ORG_ID_USE_FLAG , REQUEST_REGION_CODE , REQUEST_REGION_NAME , REQUEST_REGION_CODE_USE_FLAG , SERVER_TIME_DIFFERENCE_SEQS , MENU_USE_FLAG , OU_USE_FLAG FROM LGCOM_USER_M_V USR
WHERE TO_CHAR(APPLY_START_DATE, 'YYYYMMDD') <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_CHAR(APPLY_END_DATE, 'YYYYMMDD') > TO_CHAR(SYSDATE, 'YYYYMMDD')
AND APPLICATION_USER_ID = #{applicationUserId, jdbcType=VARCHAR }
AND APPLICATION_USER_ID IN (SELECT lumv.application_user_id FROM LGCOM_USER_M_V lumv WHERE lumv.user_name = #{erpUserName} AND lumv.subsidiary_id = 81 /* 한국으로 고정 */ AND lumv.user_name = USR.user_name)
AND USER_NAME = #{userName, jdbcType=VARCHAR }

mapper.update:
UPDATE LGCOM_USER_M lum SET lum.system_code = (SELECT m.system_code FROM ( SELECT lu.user_name , lrm.system_code , COUNT(1) FROM LGCOM_USER_ROLE_N lurn , LGCOM_ROLE_M lrm , LGCOM_USER_M lu WHERE lurn.application_user_id = lu.application_user_id AND lurn.role_code = lrm.role_code AND lu.system_code IS NULL AND NVL(lurn.apply_start_date, SYSDATE) >= trunc( SYSDATE ) AND NVL(lurn.apply_end_date, SYSDATE) < SYSDATE + 1 GROUP BY lu.user_name, lrm.system_code ORDER BY 1, 3 DESC) m WHERE m.user_name = lum.user_name AND ROWNUM = 1) WHERE lum.user_name IN
#{userNames[${index}]}
AND lum.system_code IS NULL

mapper.select:
SELECT /* User.validateAutho */
       DECODE(COUNT(1),1,'Y','N') AS "result"
  FROM LGCOM_USER_MENU_AUTHO_V
 WHERE application_user_id       = #{applicationUserId}
   AND menu_id                   = #{menuId}
   AND ROWNUM                    = 1
